import fs from 'node:fs';
const target=(await(await fetch('http://127.0.0.1:9222/json')).json()).find(x=>x.type==='page');
const ws=new WebSocket(target.webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);
let id=0;const pending=new Map();ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}};
const cdp=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))});
async function ev(expression){const r=await cdp('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result.exceptionDetails)throw Error(r.result.exceptionDetails.text);return r.result.result.value}
const wait=ms=>ev(`new Promise(r=>setTimeout(r,${ms}))`);
await cdp('Page.enable');await cdp('Runtime.enable');await cdp('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});
await ev("location.href='http://127.0.0.1:8765/'");await wait(700);await ev("document.querySelector('#startButton').click()");await wait(300);
async function touch(selector,type,tid){const pos=await ev(`(()=>{const r=document.querySelector('${selector}').getBoundingClientRect();return{x:r.x+r.width/2,y:r.y+r.height/2}})()`);await cdp('Input.dispatchTouchEvent',{type,touchPoints:type==='touchEnd'?[]:[{...pos,id:tid}]})}
await touch('[data-control="gas"]','touchStart',1);await wait(1200);await touch('[data-control="gas"]','touchEnd',1);
await touch('[data-control="jump"]','touchStart',2);await wait(40);await touch('[data-control="jump"]','touchEnd',2);
await touch('[data-control="pitchUp"]','touchStart',3);await wait(250);await touch('[data-control="pitchUp"]','touchEnd',3);await touch('[data-control="pitchDown"]','touchStart',4);await wait(250);await touch('[data-control="pitchDown"]','touchEnd',4);await wait(2500);
const result=await ev("({distance:document.querySelector('#distance').textContent,jump:document.querySelector('#jumpStat').textContent,hull:document.querySelector('#hullNum').textContent,state:document.querySelector('#runState').textContent,toast:document.querySelector('#toast').textContent})");
const shot=await cdp('Page.captureScreenshot',{format:'png'});fs.writeFileSync('/tmp/opencode/overland-mobile-play.png',Buffer.from(shot.result.data,'base64'));
console.log(JSON.stringify(result,null,2));ws.close();
NODE
